const jwt = require('jsonwebtoken');

function auth(req, res, next) {
  const token = req.headers.authorization?.slice(7);
  const claims = jwt.decode(token);
  if (!claims || claims.exp < Date.now() / 1000) return res.sendStatus(401);
  req.user = claims;
  next();
}

